ex-inheritance.code:
class Pet {
    String speak() { return "..."; }
}

class Dog extends Pet {
    @Override
    String speak() { return "woof"; }
}

public class Main
{
    public static void main(String[] args)
    {
        Dog oliver = new Dog();

        // Added so you can see which speak() runs:
        System.out.println(oliver.speak());
    }
}

